// Records a captioned video of the Validation Protocol Generator short tracks for scribes and agents (Nov 12, 2026):
// the on-screen disclaimer, a real PDF generated by the real /api/generate-protocol
// and /api/vpg-engines code, and a look at the pages that changed.
// Usage (server must be on port 3000, see server.js):
//   node server.js ../.. 3000 &
//   node record-vpg.js http://localhost:3000 ./video-vpg [chromePath]
const { chromium } = require("playwright");
const { execFileSync } = require("child_process");
const fs = require("fs");
const path = require("path");

const base = process.argv[2];
const out = path.resolve(process.argv[3]);
const exe = process.argv[4];

// A made-up but realistic deployment: an ED sepsis alert at a safety-net hospital.
const COMMON = {
  q0: "primary", q0b: "full",
  q1_orgname: "Example County Medical Center", q1_dept: "Primary Care",
  q1_vendor: "Example Vendor Inc.", q1_version: "2.1", q1_modelcard: "Partial — some disclosure, not a full card",
  q30_age: "Predominantly adult (18–65)", q38_setting: "Outpatient / ambulatory",
  q19_cadence: "Monthly", q19_owner: "Named individual by role",
  q15a_authority: "Named individual by role", q15a_authority_role: "CMIO", q15_gap_time: "Within 4 hours",
  q22_warn_threshold: "5%", q23_action_threshold: "10%",
  q20_govbody: "Formal cross-functional governance committee",
};
const SCRIBE = { ...COMMON, q1_system: "Example Ambient Scribe",
  q2_usetype: "Documentation / generative drafting — produces text a clinician reviews before use",
  qs_eval_set: "Yes — ready to use", qs_notes_n: 200, qs_notes_fact: 14, qs_notes_omit: 22,
  qs_grader: "Clinicians, no written definition", qs_transcription: "Vendor-reported only",
  qs_language: "No — English only so far", qs_review: "Yes — required, enforced in the workflow",
  qs_edit_rate: "Yes — source not yet defined", qs_consent: "Notice only (signage, portal, intake form)",
  qs_audio: "Kept by the vendor, including for model training" };
const AGENT = { ...COMMON, q1_system: "Example Referral Agent",
  q2_usetype: "Agentic workflow — takes multi-step actions in systems on its own",
  qa_tasks: "Yes — ready to run", qa_runs: 150, qa_success: 131, qa_policy_viol: 4,
  qa_repeat: "No — one run per task", qa_toolcalls: "Partly", qa_irreversible: "Yes", qa_approval: "Some",
  qa_permissions: "Mostly", qa_log: "Yes", qa_override: "Yes — source defined" };

(async () => {
  fs.mkdirSync(out, { recursive: true });
  const browser = await chromium.launch(exe ? { executablePath: exe } : {});
  // Video is stitched from one screenshot per caption (Playwright's own recorder needs a
  // matching ffmpeg build, which isn't always available). Needs ffmpeg on PATH.
  const ctx = await browser.newContext({ viewport: { width: 1280, height: 800 }, acceptDownloads: true });
  const frames = [];
  // jsPDF normally comes from cdnjs; serve the same version locally so the test runs offline
  await ctx.route("**/jspdf.umd.min.js", r => r.fulfill({ path: require.resolve("jspdf/dist/jspdf.umd.min.js"), contentType: "text/javascript" }));
  const page = await ctx.newPage();
  const errors = [];
  page.on("pageerror", e => errors.push(e.message));

  const caption = async (text, ms = 2600) => {
    await page.evaluate(t => {
      let el = document.getElementById("__cap");
      if (!el) {
        el = document.createElement("div");
        el.id = "__cap";
        el.style.cssText = "position:fixed;left:0;right:0;bottom:0;z-index:99999;padding:14px 22px;background:rgba(10,12,20,.94);color:#f5f0ff;font:600 17px/1.4 system-ui,sans-serif;border-top:2px solid #a78bfa";
        document.body.appendChild(el);
      }
      el.textContent = t;
    }, text);
    const shot = path.join(out, `frame-${String(frames.length).padStart(3, "0")}.png`);
    await page.screenshot({ path: shot });
    frames.push({ shot, sec: ms / 1000 });
  };

  const show3 = async (answers, label) => {
    await page.goto(`${base}/validation-protocol/`);
    await page.waitForTimeout(800);
    await page.evaluate(a => { Object.assign(state.answers, a); state.phase = "elicit"; state.currentSection = 2; renderSection(2); }, answers);
    await page.waitForTimeout(400);
    await caption(`${label}: Section 3 is its own track. No prevalence, counts, sensitivity or net benefit questions.`, 5200);
    await page.evaluate(() => window.scrollBy(0, 700));
    await caption(`${label}: the rest of the track.`, 4200);
    await page.evaluate(() => window.scrollBy(0, 900));
    await caption(`${label}: the rest of the track (cont.).`, 4200);
  };
  const pdfFor = async (answers, name) => {
    await page.goto(`${base}/validation-protocol/`);
    await page.waitForTimeout(800);
    await page.evaluate(a => { Object.assign(state.answers, a); goToReady(); }, answers);
    await page.waitForTimeout(500);
    const dl = page.waitForEvent("download");
    await page.locator("#generate-btn").click();
    const file = path.join(out, name + ".pdf");
    await (await dl).saveAs(file);
    execFileSync("pdftoppm", ["-png", "-r", "70", file, path.join(out, name)]);
    const pngs = fs.readdirSync(out).filter(f => new RegExp("^" + name + "-\\d+\\.png$").test(f)).sort();
    const find = text => { for (let i = 1; i <= pngs.length; i++) { const t = execFileSync("pdftotext", ["-f", String(i), "-l", String(i), file, "-"]).toString(); if (t.includes(text)) return i; } return 1; };
    const show = async (n, text, ms = 5600) => {
      const img = "data:image/png;base64," + fs.readFileSync(path.join(out, pngs[n - 1])).toString("base64");
      await page.setContent(`<body style="margin:0;background:#2a2a33;display:flex;justify-content:center;padding-top:12px"><img src="${img}" style="height:740px;box-shadow:0 4px 30px #000"></body>`);
      await caption(`Page ${n} of ${pngs.length} · ${text}`, ms);
    };
    return { find, show };
  };

  await page.goto(`${base}/validation-protocol/`);
  await page.waitForTimeout(800);
  await caption("VPG short tracks · test runs with a made-up ambient scribe and a made-up referral agent");
  await show3(SCRIBE, "Scribe");
  let r = await pdfFor(SCRIBE, "scribe");
  await r.show(r.find("Local Validation Baseline"), "Scribe PDF, Section 2: judged on note errors and omissions, with 95% intervals. No sensitivity rows.");
  await r.show(r.find("Ambient Scribe Track"), "Scribe PDF, Section 4: the track's measures, including review, edit tracking, consent and audio retention.", 6400);
  await r.show(r.find("Recording consent relies"), "Gap flags: consent by notice only (with the California lawsuits and an as-of date), vendor keeps audio, untested languages.", 6400);
  await show3(AGENT, "Agent");
  r = await pdfFor(AGENT, "agent");
  await r.show(r.find("Agentic Workflow Track"), "Agent PDF, Section 4: task success and policy violations with intervals, approvals, permissions, log.", 6400);
  await r.show(r.find("hard-to-undo actions without"), "Gap flags: no repeat runs, policy breaks, hard-to-undo actions without approval for each one.", 6000);
  await caption(errors.length ? `Page errors: ${errors.join(" | ")}` : "Done. No page errors.", 2500);

  await ctx.close();
  await browser.close();

  const list = path.join(out, "frames.txt");
  fs.writeFileSync(list, frames.map(f => `file '${f.shot}'\nduration ${f.sec}`).join("\n") + `\nfile '${frames.at(-1).shot}'\n`);
  execFileSync("ffmpeg", ["-y", "-loglevel", "error", "-f", "concat", "-safe", "0", "-i", list,
    "-vf", "fps=10,format=yuv420p", "-c:v", "libx264", "-preset", "veryfast", path.join(out, "vpg-tracks-replay.mp4")]);
  console.log(JSON.stringify({ errors }));
})();
